import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CZqXuAiL.js";const m=JSON.parse('{"title":"Configuration Reference","description":"Every Ask Access setting — config file values, environment variables, admin panel policy, and permission presets.","frontmatter":{"title":"Configuration Reference","description":"Every Ask Access setting — config file values, environment variables, admin panel policy, and permission presets."},"headers":[],"relativePath":"ask-access/configuration/reference.md","filePath":"ask-access/configuration/reference.md","lastUpdated":1785513641000}'),d={name:"ask-access/configuration/reference.md"};function n(r,e,i,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Ask Access is configured in two places: the <strong>admin settings page</strong> (stored in the database, no restart needed) and the <strong><code>config/askaccess.php</code></strong> file (overridable via environment variables).</p><hr><h2 id="admin-panel-settings" tabindex="-1">Admin panel settings <a class="header-anchor" href="#admin-panel-settings" aria-label="Permalink to &quot;Admin panel settings&quot;">​</a></h2><p>Found at <strong>Admin → Extensions → Ask Access</strong> (Blueprint installs). Stored in the <code>askaccess_admin_settings</code> table and applied immediately.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td>Access mode</td><td><code>everyone</code> · <code>allowlist</code> · <code>blacklist</code></td><td><code>everyone</code></td><td>Who may use Ask Access at all. Root admins always bypass this.</td></tr><tr><td>Allowlist</td><td>list of emails</td><td>empty</td><td>When mode is <code>allowlist</code>, only these emails can use the feature.</td></tr><tr><td>Blacklist</td><td>list of emails</td><td>empty</td><td>When mode is <code>blacklist</code>, these emails are excluded.</td></tr><tr><td>Request decay (hours)</td><td>integer, 1–8760</td><td><code>24</code></td><td>How long a pending request stays valid before it is auto-expired by the scheduler.</td></tr><tr><td>Block rate limit</td><td>integer, 1–1000</td><td><code>10</code></td><td>Max &quot;block user&quot; actions a single account may perform per minute.</td></tr></tbody></table><p><strong>When to change:</strong></p><ul><li>Set mode to <code>allowlist</code> on hosts where only paying customers should share servers.</li><li>Raise <strong>request decay</strong> if your users are slow to respond (e.g. <code>168</code> = one week).</li><li>Emails in lists are normalized (lower-cased, validated, de-duplicated) — paste them one per line or comma-separated.</li></ul><div class="info custom-block"><p class="custom-block-title">Common mistake</p><p>Switching to <code>allowlist</code> with an empty list disables the feature for <strong>everyone except root admins</strong>. Add emails first, then switch the mode.</p></div><hr><h2 id="environment-config-file" tabindex="-1">Environment / config file <a class="header-anchor" href="#environment-config-file" aria-label="Permalink to &quot;Environment / config file&quot;">​</a></h2><p><code>config/askaccess.php</code> — every value can be set via <code>.env</code> without touching the file.</p><table tabindex="0"><thead><tr><th>Env variable</th><th>Config key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>ASKACCESS_MAX_PENDING</code></td><td><code>max_pending_per_user</code></td><td>int</td><td><code>25</code></td><td>Maximum pending outgoing requests one user may have open at once. Anti-spam cap.</td></tr><tr><td><code>ASKACCESS_CREATE_RATE_LIMIT</code></td><td><code>create_rate_limit</code></td><td>int</td><td><code>15</code></td><td>Max requests a user may <strong>create</strong> within the rolling window below.</td></tr><tr><td><code>ASKACCESS_CREATE_RATE_WINDOW</code></td><td><code>create_rate_window_minutes</code></td><td>int</td><td><code>60</code></td><td>Window (minutes) for the creation rate limit.</td></tr><tr><td><code>ASKACCESS_MAX_SERVERS_PER_GRANT</code></td><td><code>max_servers_per_grant</code></td><td>int</td><td><code>250</code></td><td>Safety cap on how many servers a single &quot;all servers of this user&quot; approval can touch.</td></tr><tr><td><code>ASKACCESS_REQUEST_TTL_DAYS</code></td><td><code>request_ttl_days</code></td><td>int</td><td><code>14</code></td><td><strong>Unused</strong> — kept for backward compatibility. Request expiry is controlled by the admin <strong>request decay (hours)</strong> setting instead.</td></tr></tbody></table><p>After changing any of these, clear the config cache:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:clear</span></span></code></pre></div><hr><h2 id="permission-presets" tabindex="-1">Permission presets <a class="header-anchor" href="#permission-presets" aria-label="Permalink to &quot;Permission presets&quot;">​</a></h2><p>Defined under <code>presets</code> in <code>config/askaccess.php</code>. The <code>full</code> preset is <strong>not</strong> a static list — it expands at runtime to every permission registered in the panel. Every preset automatically includes <code>websocket.connect</code> so grantees can actually load the server console.</p><table tabindex="0"><thead><tr><th>Preset</th><th>UI label</th><th>Includes</th></tr></thead><tbody><tr><td><code>read</code></td><td>Read-only</td><td>Console view, file read, backup/allocation/startup/database/schedule/activity read. Nothing that changes state.</td></tr><tr><td><code>standard</code></td><td>Standard</td><td>Everything in <code>read</code>, plus start/stop/restart, file create/update/archive, backup create/download, startup edit.</td></tr><tr><td><code>full</code></td><td>Full access</td><td>Every registered panel permission, including <code>accessmanager.manage</code>.</td></tr></tbody></table><p><strong>When to change:</strong> edit the <code>presets</code> arrays if your panel has custom permissions from other addons you want included in (or excluded from) <code>read</code>/<code>standard</code>. Unknown permission strings are stripped at runtime, so a typo can&#39;t grant anything.</p><div class="warning custom-block"><p class="custom-block-title"><code>full</code> implies delegation</p><p>Because <code>full</code> contains <code>accessmanager.manage</code>, anyone granted Full access can grant and revoke access for that server themselves. If you don&#39;t want that, remove <code>accessmanager</code> from the permission list or avoid offering the preset.</p></div><hr><h2 id="the-accessmanager-manage-permission" tabindex="-1">The <code>accessmanager.manage</code> permission <a class="header-anchor" href="#the-accessmanager-manage-permission" aria-label="Permalink to &quot;The `accessmanager.manage` permission&quot;">​</a></h2><p>The installer adds a custom permission group to <code>app/Models/Permission.php</code>:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Granted by</th><th>Effect</th></tr></thead><tbody><tr><td><code>accessmanager.manage</code></td><td>Owner via the Active tab / subuser editor</td><td>The subuser can manage access <strong>for that server</strong> from their own Server Access page: add/remove users, edit permissions, set expiry.</td></tr></tbody></table><ul><li>Scoped per server — a manager on server A has no power over server B.</li><li>Managers cannot remove the owner and cannot escalate their own permissions beyond what exists on the panel.</li><li>Uninstalling the addon removes this permission group cleanly.</li></ul>',26)])])}const g=t(d,[["render",n]]);export{m as __pageData,g as default};
